from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class PlanUploadResponseASMV1(SchemaObject):
    plan_id = SchemaField(name='plan_id', not_null=True)
    procedure_state = SchemaField(name='procedure_state', not_null=True)
    raml_parsing_errors = SchemaField(name='raml_parsing_errors')
    incorrect_objects_feedback = SchemaField(name='incorrect_objects_feedback', not_null=True)
    action_id = SchemaField(name='action_id', not_null=True)
    links = SchemaField(name="links", optional=True)
    status = SchemaField(name='status', not_null=True)
    error_message = SchemaField(name='error_message', optional=True)

    def __init__(self, plan_id, procedure_state, raml_parsing_errors, incorrect_objects_feedback,
                 action_id, links, status, error_message):
        self.plan_id = plan_id
        self.procedure_state = procedure_state
        self.raml_parsing_errors = raml_parsing_errors
        self.incorrect_objects_feedback = incorrect_objects_feedback
        self.action_id = action_id
        self.links = links
        self.status = status
        self.error_message = error_message

        super(PlanUploadResponseASMV1, self).__init__()
